variables.input:
timeseries n = count(zeebe.health), by: {k8s.namespace.name}
| fields k8s.namespace.name
| sort k8s.namespace.name asc

3.query:
timeseries role = max(atomix.role),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

5.query:
timeseries restarts = sum(dt.kubernetes.container.restarts),
  by: {k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

8.query:
timeseries exporter_events_per_sec = sum(zeebe.exporter.events.total, rate:1s),
  by: {k8s.pod.name, partition, exporter},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

9.query:
timeseries requests_per_sec = sum(zeebe.gateway.total.requests, rate:1s),
  by: {requestType},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

11.query:
timeseries instance_events_per_sec = sum(zeebe.element.instance.events.total, rate:1s),
  by: {type, action, eventType},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

19.query:
timeseries bootstrap_time = max(atomix.partition.server.bootstrap.time),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

20.query:
timeseries recovery_time = max(zeebe.stream.processor.startup.recovery.time),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

21.query:
timeseries transition_latency = max(zeebe.leader.transition.latency),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(partition, array($Partition)) and in(k8s.pod.name, array($Pod))}

23.query:
timeseries {
    pending = max(zeebe.cluster.changes.operations.pending),
    completed = max(zeebe.cluster.changes.operations.completed)
  },
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))},
  union: true
